<?php
require "db.php";require "functions.php";need_role("admin");
if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$action=$_POST["action"]??"";
 if(in_array($action,["approve","reject"],true)){$sid=filter_input(INPUT_POST,"staff_id",FILTER_VALIDATE_INT);if($sid){if($action==="approve"){$q=$pdo->prepare("UPDATE users SET is_approved=1 WHERE id=? AND role='staff'");$q->execute([$sid]);flash("Staff account approved.");}else{$q=$pdo->prepare("DELETE FROM users WHERE id=? AND role='staff' AND is_approved=0");$q->execute([$sid]);flash("Pending staff registration removed.");}}header("Location: admin_dashboard.php#approvals");exit;}
 if($action==="assign"){$cid=filter_input(INPUT_POST,"complaint_id",FILTER_VALIDATE_INT);$sid=filter_input(INPUT_POST,"staff_id",FILTER_VALIDATE_INT);$q=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='staff' AND is_approved=1");$q->execute([$sid]);if(!$cid||!$q->fetch())flash("Choose a valid approved staff member.","error");else{$q=$pdo->prepare("UPDATE complaints SET assigned_staff_id=?,status=CASE WHEN status='Submitted' THEN 'Assigned' ELSE status END WHERE id=?");$q->execute([$sid,$cid]);flash("Complaint assignment saved.");}header("Location: admin_dashboard.php#complaints");exit;}
}
$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='Submitted') submitted,SUM(status='In Progress') progress,SUM(status='Resolved') resolved FROM complaints")->fetch();
$pending=$pdo->query("SELECT id,full_name,email,college_id,created_at FROM users WHERE role='staff' AND is_approved=0 ORDER BY created_at")->fetchAll();
$staff=$pdo->query("SELECT id,full_name FROM users WHERE role='staff' AND is_approved=1 ORDER BY full_name")->fetchAll();
$rows=$pdo->query("SELECT c.*,u.full_name student_name,u.email student_email FROM complaints c JOIN users u ON u.id=c.student_id ORDER BY FIELD(c.status,'Submitted','Assigned','In Progress','Resolved','Rejected'),c.created_at DESC LIMIT 200")->fetchAll();
$title="Admin dashboard";require "layout.php";?>
<div class="page-heading"><div><div class="eyebrow">CAMPUS CONTROL CENTER</div><h1>Welcome, <span class="green">Admin.</span></h1><p>Approve staff, assign complaints, and coordinate campus resolution.</p></div><span class="pill">Administrator</span></div>
<div class="stat-grid"><div class="stat-card"><small>Total complaints</small><strong><?= (int)($stats["total"]??0)?></strong><span>All campus reports</span></div><div class="stat-card"><small>Awaiting assignment</small><strong><?= (int)($stats["submitted"]??0)?></strong><span>Need staff attention</span></div><div class="stat-card"><small>In progress</small><strong><?= (int)($stats["progress"]??0)?></strong><span>Being resolved</span></div><div class="stat-card"><small>Resolved</small><strong><?= (int)($stats["resolved"]??0)?></strong><span>Completed reports</span></div></div>
<section class="panel section" id="approvals"><div class="panel-heading"><div><h2>Staff approval queue <span class="pill"><?=count($pending)?></span></h2><p>Approve staff before they can sign in.</p></div></div><?php if(!$pending):?><div class="empty"><h3>You're all caught up.</h3><p>No staff accounts are waiting for approval.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Staff ID</th><th>Requested</th><th>Action</th></tr></thead><tbody><?php foreach($pending as $s):?><tr><td><b><?=e($s["full_name"])?></b><div class="muted small"><?=e($s["email"])?></div></td><td><?=e($s["college_id"]??"—")?></td><td><?=e(date("M j, Y",strtotime($s["created_at"])))?></td><td><div class="actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="staff_id" value="<?=(int)$s["id"]?>"><button class="btn btn-primary btn-small">Approve</button></form><form method="post" data-confirm="Remove this pending staff registration?"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="reject"><input type="hidden" name="staff_id" value="<?=(int)$s["id"]?>"><button class="btn btn-danger btn-small">Reject</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel section" id="complaints"><div class="panel-heading"><div><h2>Complaint management</h2><p>Assign each complaint to an approved staff member.</p></div><input class="search" type="search" placeholder="Search complaints..." data-filter="admin-table"></div><?php if(!$rows):?><div class="empty"><h3>No reports submitted yet</h3><p>Student complaints will appear here.</p></div><?php else:?><div class="table-wrap"><table id="admin-table"><thead><tr><th>Complaint / Student</th><th>Priority</th><th>Status</th><th>Assign staff</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r["title"])?></b><div class="muted small">#<?=(int)$r["id"]?> · <?=e($r["category"])?> · <?=e($r["location"]?: "No location")?></div><p class="table-desc"><?=e($r["description"])?></p><div class="muted small">Student: <?=e($r["student_name"])?> · <?=e($r["student_email"])?></div></td><td><?=e($r["priority"])?></td><td><?=status_badge($r["status"])?></td><td><form method="post" class="form compact"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="complaint_id" value="<?=(int)$r["id"]?>"><select name="staff_id" required><option value="">Choose staff</option><?php foreach($staff as $s):?><option value="<?=(int)$s["id"]?>" <?=((int)$r["assigned_staff_id"]===(int)$s["id"]?"selected":"")?>><?=e($s["full_name"])?></option><?php endforeach;?></select><button class="btn btn-primary btn-small" <?=(!$staff?"disabled":"")?>>Assign</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require "end.php";?>
